package tokenanalytics

import (
	"math/big"
	"strings"
	"testing"
	"time"

	"github.com/goccy/go-json"
	"github.com/stretchr/testify/require"

	"github.com/ice-blockchain/heimdall/accounts"
)

func TestTransactionValidation(t *testing.T) {
	tu := &tokenAnalyticsUsers{
		cfg: &config{BondingCurve: struct {
			SmartContractAddress                string                         `yaml:"smartContractAddress"`
			BurnAddress                         string                         `yaml:"burnAddress"`
			TokenFactorySmartContractAddress    string                         `yaml:"tokenFactorySmartContractAddress"`
			BondingCurveProgressUpdateFrequency time.Duration                  `yaml:"bondingCurveProgressUpdateFrequency"`
			CreateTokenDefaults                 map[string]createTokenDefaults `yaml:"createTokenDefaults" mapstructure:"createTokenDefaults"`
		}{CreateTokenDefaults: make(map[string]createTokenDefaults), SmartContractAddress: "0x4ab1807ff59a391503b0c8e28d2647bd9a7ecda1"}},
	}
	db, release := helperCreateDB(t)
	defer release()

	tu.ingestedDataDB = db
	tu.cfg.BondingCurve.CreateTokenDefaults["post"] = createTokenDefaults{
		InitialPrice:           "10000",
		FinalPrice:             "100000",
		EmissionVolume:         "1000000000000000000000",
		BondingCurveAlgAddress: "0x000000000000000000000000000000000000dead",
		FeeSponsorAddress:      "0x000000000000000000000000000000000000dead",
		FeeSponsorId:           "post",
	}
	tu.cfg.BondingCurve.CreateTokenDefaults["profile"] = createTokenDefaults{
		InitialPrice:           "1000000",
		FinalPrice:             "100000000",
		EmissionVolume:         "1000000000000000000000",
		BondingCurveAlgAddress: "0x000000000000000000000000000000000000dead",
		FeeSponsorAddress:      "0x000000000000000000000000000000000000dead",
		FeeSponsorId:           "profile",
	}
	t.Run("tx gets passed when non bonding-curve is called", func(t *testing.T) {
		txNotToBondingCurveData := `{
          "kind": "UserOperations",
          "userOperations": [
            {
              "to": "0x000000000000000000000000000000000001dead",
              "data": ""
            },
            {
              "to": "0x000000000000000000000000000000000002dead",
              "data": ""
            }
          ]
        }`
		var txNotToBondingCurve accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txNotToBondingCurveData), &txNotToBondingCurve))
		require.NoError(t, tu.ValidateTransaction(t.Context(), txNotToBondingCurve))
	})
	t.Run("bonding curve params are validated when non-first swap occurs", func(t *testing.T) {
		txFirstSwapData := `{
          "kind": "UserOperations",
          "userOperations": [
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            },
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            }
          ]
        }`
		var txFirstSwap accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txFirstSwapData), &txFirstSwap))
		err := tu.ValidateTransaction(t.Context(), txFirstSwap)
		require.Error(t, err, ErrValidationFailed)
		require.True(t, strings.Contains(err.Error(), "expected 0x000000000000000000000000000000000000dead, got 0x0000000000000000000000000000000000000000"))
	})
	t.Run("twisted swap (fat address with 2 tokens)", func(t *testing.T) {
		tu.cfg.BondingCurve.CreateTokenDefaults["post"] = createTokenDefaults{
			InitialPrice:           "583400000000000",
			FinalPrice:             "9749900000000000",
			EmissionVolume:         "1000000000000000000000000000",
			BondingCurveAlgAddress: "0x000000000000000000000000000000000000dead",
			FeeSponsorAddress:      "0x000000000000000000000000000000000000dead",
			FeeSponsorId:           "post",
		}
		tu.cfg.BondingCurve.CreateTokenDefaults["profile"] = createTokenDefaults{
			InitialPrice:           "583400000000000",
			FinalPrice:             "9749900000000000",
			EmissionVolume:         "1000000000000000000000000000",
			BondingCurveAlgAddress: "0x000000000000000000000000000000000000dead",
			FeeSponsorAddress:      "0x000000000000000000000000000000000000dead",
			FeeSponsorId:           "profile",
		}

		tu.bondingCurve = &mockBondingCurveForBalanceUpdater{
			pricing: big.NewInt(1000000000000000000),
		}

		swapData := `{
		  "kind": "UserOperations",
		  "userOperations": [
			{
			  "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
			  "data": ""
			}
		  ],
		  "feeSponsorId": "fs-01jg7-2dotc-esmbtjcn9udvpvk8"
		}`

		var tx accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(swapData), &tx))
		err := tu.ValidateTransaction(t.Context(), tx)
		require.NoError(t, err)
	})
}
